import{_ as a,o,c as i,a2 as c}from"./chunks/framework.CgxQ0r6v.js";const m=JSON.parse('{"title":"Práctica 3: Objetivos y Plan de Acción","description":"Ejercicios prácticos y código fuente en JavaScript para Proyecto Sociotecnológico I","frontmatter":{"title":"Práctica 3: Objetivos y Plan de Acción","description":"Ejercicios prácticos y código fuente en JavaScript para Proyecto Sociotecnológico I"},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_I/ejercicios/I-I/practica-3.md","filePath":"materias/Proyecto_Sociotecnologico_I/ejercicios/I-I/practica-3.md"}'),t={name:"materias/Proyecto_Sociotecnologico_I/ejercicios/I-I/practica-3.md"};function n(r,e,s,d,l,u){return o(),i("div",null,[...e[0]||(e[0]=[c('<h1 id="💻-practica-3-objetivos-y-plan-de-accion" tabindex="-1">💻 Práctica 3: Objetivos y Plan de Acción <a class="header-anchor" href="#💻-practica-3-objetivos-y-plan-de-accion" aria-label="Permalink to &quot;💻 Práctica 3: Objetivos y Plan de Acción&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📌 Información de Cátedra</p><ul><li><strong>Materia:</strong> Proyecto Sociotecnológico I</li><li><strong>Trimestre:</strong> I-I</li><li><strong>Guía Teórica Vinculada:</strong> <a href="/pnfi-doc/materias/Proyecto_Sociotecnologico_I/documentacion/I-I/Lectura_Catedra_Evaluacion_3">Lectura de Cátedra (L3)</a></li></ul></div><hr><h2 id="📋-enunciados-y-actividades-practicas" tabindex="-1">📋 Enunciados y Actividades Prácticas <a class="header-anchor" href="#📋-enunciados-y-actividades-practicas" aria-label="Permalink to &quot;📋 Enunciados y Actividades Prácticas&quot;">​</a></h2><p>Esta guía contiene actividades para aprender a organizar los datos recolectados, analizarlos y presentarlos ante la comunidad.</p><hr><ol><li><p><strong>Tabulación de Datos con Encuestas Ficticias</strong> Suponga que aplicó una encuesta a 20 docentes sobre su nivel de manejo de herramientas ofimáticas. Los resultados ficticios son: 12 respondieron &quot;No saben usar Excel&quot;, 5 respondieron &quot;Lo usan a nivel básico&quot; y 3 respondieron &quot;Lo dominan&quot;. Calcule los porcentajes de cada categoría y elabore un gráfico de torta representativo (puede dibujarlo a mano o usar una herramienta digital).</p></li><li><p><strong>Análisis de Involucrados</strong> Para un proyecto de Soporte Técnico en un liceo, identifique y clasifique a los siguientes actores: Directora, Estudiantes del liceo, Obreros, Secretaria administrativa, Consejo Comunal del sector, Padres y representantes. Clasifique a cada uno como: Beneficiario Directo, Beneficiario Indirecto o Posible Opositor. Justifique cada clasificación.</p></li><li><p><strong>Redacción del Contraste Técnico-Social</strong> Un consejo comunal le pide a su equipo que &quot;les monte un sistema de facturación&quot;. Sin embargo, tras el diagnóstico, ustedes descubren que no tienen internet, las computadoras no encienden y nadie sabe usar software. Redacte un párrafo de 10 líneas (en tercera persona) explicando el contraste entre la necesidad sentida por la comunidad y la necesidad técnica real detectada. Proponga una solución acorde al Trayecto I.</p></li><li><p><strong>Simulación de Socialización</strong> En equipos, preparen una presentación de 10 minutos donde expongan los resultados ficticios de un diagnóstico a una &quot;comunidad&quot; (el resto del salón). Deben usar gráficos simples, hablar sin tecnicismos excesivos y al final pedir la &quot;validación&quot; del público (que la comunidad ficticia diga si está de acuerdo con el problema identificado).</p></li></ol><hr><hr>',9)])])}const g=a(t,[["render",n]]);export{m as __pageData,g as default};
